import React, { useState } from "react";

const Login = () => {
  const [username, setUsername] = useState("");
  const [pwd, setPwd] = useState("");
  return (
    <div>
      <h4>Login</h4>
      <form className="login-form">
        <input type="text" value={username} />
        <input type="text" value={pwd} />
      </form>
    </div>
  );
};

export default Login;
